import {sources,nav,pageTitles,research,topicLabels,flights,tests,news,curriculum} from './content.mjs';
import {currentResearch} from './current-research.mjs';
const esc = value => String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function render(page,lang) {
 const ko=lang==='ko', asset=ko?'../assets/':'assets/', root=ko?'../':'', t=(en,kr)=>ko?kr:en, loc=o=>o[lang];
 const href=p=>{const [name,fragment]=p.split('#');return `${name}.html${fragment?`#${fragment}`:''}`;};
 const link=(url,label,classes='text-link')=>`<a class="${classes}" href="${esc(url)}">${label}</a>`;
 const internal=(p,label,classes='text-link')=>link(href(p),label,classes);
 const dimensions={'rocket-full.webp':[1351,2400],'rocket-detail.webp':[1800,2400],'field-team.webp':[2400,1351],'team.webp':[2400,1800],'founder.webp':[2400,2400],'award.webp':[2400,2040],'psi-logo.png':[1280,317],'tms-test-2026-04-08-preview.webp':[2400,1187]};
 const image=(name,alt,classes='',loading='lazy')=>{const size=dimensions[name];if(!size)throw new Error(`Missing image dimensions: ${name}`);return `<img class="${classes}" src="${asset}${name}" width="${size[0]}" height="${size[1]}" alt="${esc(alt)}" loading="${loading}" decoding="async">`;};
 const figure=(name,alt,caption,classes='')=>`<figure class="${classes}">${image(name,alt)}<figcaption>${caption}</figcaption></figure>`;
 const pageHead=(title,intro,extra='')=>`<header class="page-head wrap${page==='research'?' research-page-head':''}"><div><p class="affiliation">${t('PSI / POSTECH','PSI / 포스텍 항공우주연구회')}</p><h1>${title}</h1></div><div class="page-intro"><p>${intro}</p>${extra}</div></header>`;
 const sectionHeading=(title,body='')=>`<div class="section-heading"><h2>${title}</h2>${body?`<p>${body}</p>`:''}</div>`;
 const testPlot=(wide=false)=>`<figure class="test-plot${wide?' wrap':''}"><a href="${asset}tms-test-2026-04-08.png" aria-label="${t('Open the full-size thrust graph from the 8 April 2026 test','2026년 4월 8일 시험의 추력 그래프 원본 크기로 열기')}">${image('tms-test-2026-04-08-preview.webp',t('Time-series thrust graph with corrected load-cell readings and a filtered trace from the 8 April 2026 test','2026년 4월 8일 시험에서 얻은 보정 로드셀 신호와 필터링 결과의 시간별 추력 그래프'))}</a><figcaption>${t('Thrust measurements from the 8 April 2026 test, showing corrected load-cell readings and the filtered trace.','2026년 4월 8일 연소 시험의 시간별 추력 측정 기록. 보정된 로드셀 신호와 필터링 결과를 함께 보여줍니다.')} <span>${link(`${asset}tms-test-2026-04-08.png`,t('Open full-size graph','원본 그래프 열기'))} ${link(`${sources.tests}/blob/main/tests/2026-04-08/index.md`,t('Read the test record','시험 기록 읽기'))}</span></figcaption></figure>`;
 const media=(hero=false)=>`<div class="flight-media${hero?' hero-media':''}" data-media-stage data-asset-base="${asset}">
   <div class="media-screen" id="flight-view" role="tabpanel" aria-labelledby="view-pad"><video data-flight-video src="${asset}launch.mp4" poster="${asset}launch-poster.webp" preload="metadata" playsinline controls tabindex="0" aria-describedby="flight-description" aria-label="${t('PSI rocket launch footage','PSI 로켓 발사 영상')}"></video>${hero?`<div class="hero-identity"><h1>${t('PSI at the launch site.','포스텍에서, 발사 현장까지.')}</h1><p>${t('Student aerospace at POSTECH. We design, build and study rockets and unmanned aircraft.','PSI는 포스텍 학생들이 로켓과 무인비행체를 설계하고, 제작하고, 연구하는 항공우주연구회입니다.')}</p>${internal('pslv',t('Explore the PSLV programme','PSLV 로켓 프로젝트 살펴보기'))}</div>`:''}<button class="media-play" data-media-play hidden aria-label="${t('Play launch footage','발사 영상 재생')}"><span aria-hidden="true">▶</span><span data-play-label>${t('Watch the launch','발사 영상 보기')}</span></button></div>
   <div class="media-bar"><div class="media-tabs" role="tablist" aria-label="${t('Choose a flight viewpoint','영상 시점 선택')}"><button id="view-pad" role="tab" aria-controls="flight-view" aria-selected="true" data-media="pad">${t('At the launch pad','발사대에서')}</button><button id="view-onboard" role="tab" aria-controls="flight-view" aria-selected="false" tabindex="-1" data-media="onboard">${t('On board the rocket','로켓 안에서')}</button></div><p id="flight-description" data-media-description>${t('The rocket lifts off from the stand, leaving smoke at the pad. Original field sound plays with the video.','발사대에 서 있던 로켓이 이륙하고 연기가 남습니다. 현장 소리가 영상과 함께 재생됩니다.')}</p></div>
   <p class="media-failure" data-media-failure hidden>${t('The video could not load. Try opening the video file directly.','영상을 불러오지 못했습니다. 영상 파일을 직접 열어 보세요.')} ${link(`${asset}launch.mp4`,t('Open this video file','이 영상 파일 열기'))}</p>
 </div>`;
 const flightLedger=()=>`<div class="flight-ledger">${flights.map(f=>`<article><div class="flight-date"><time datetime="${f.date}">${f.date}</time><span>${f.vehicle}</span></div><div><h3>${loc(f.title)}</h3><p>${loc(f.body)}</p>${link(f.url,t('View original record','원본 기록 보기'))}</div></article>`).join('')}</div>`;
 const testTable=()=>`<div class="test-list">${tests.map(item=>`<article class="test-record"><div class="test-date"><time datetime="${item.date}">${item.date}</time>${link(item.url,t('Test record','시험 기록'))}</div><dl><div><dt>${t('Peak thrust','최대 추력')}</dt><dd>${item.thrust} <span>N</span></dd></div><div><dt>${t('Total impulse','총 충격량')}</dt><dd>${item.impulse} <span>N·s</span></dd></div></dl><p>${loc(item.note)}</p></article>`).join('')}</div>`;
 const hardware=()=>`<div class="hardware" data-hardware-explorer><div class="hardware-portrait">${image('rocket-full.webp',t('A full-length PSI rocket standing upright at the launch field','발사 현장에 세워진 PSI 로켓의 전체 모습'))}<p>${t('The complete vehicle, photographed at the field.','현장에서 촬영한 로켓의 전체 모습.')}</p></div><div class="hardware-content"><h2>${t('A vehicle made<br>of connected systems.','여러 시스템이 만나<br>하나의 비행체로.')}</h2><p>${t('Follow a few of the engineering questions behind the photographed vehicle. Structure, measurements and recovery have to work together across a flight.','사진 속 비행체를 만드는 공학적 질문을 살펴보세요. 구조, 측정, 회수 시스템은 비행 내내 함께 작동해야 합니다.')}</p><div class="hardware-tabs" role="tablist" aria-label="${t('Explore rocket systems','로켓 시스템 살펴보기')}">
 ${[['structure','Airframe','기체 구조'],['electronics','Avionics','에비오닉스'],['recovery','Recovery','회수']].map(([id,en,kr],i)=>`<button id="tab-${id}" role="tab" aria-selected="${i===0}" aria-controls="panel-${id}" tabindex="${i===0?'0':'-1'}" data-hardware="${id}">${t(en,kr)}</button>`).join('')}</div>
 <div class="hardware-panel" id="panel-structure" role="tabpanel" aria-labelledby="tab-structure" data-hardware-panel="structure">${image('rocket-detail.webp',t('Close photograph of the PSI rocket body and its assembled hardware','PSI 로켓 동체와 조립된 하드웨어의 근접 사진'),'hardware-detail')}<h3>${t('A structure that brings the vehicle together','비행체를 연결하는 구조')}</h3><p>${t('The airframe is the physical connection between propulsion, flight electronics and recovery hardware. PSI’s public research includes carbon-fibre bodies and the dynamic stability of stage separation. The exterior photograph is a view of real hardware, not a cutaway of its internals.','기체 구조는 추진 장치, 비행 전자장치, 회수 장치를 물리적으로 연결합니다. PSI는 탄소섬유 동체와 단 분리 과정의 동적 안정성을 연구해 왔습니다. 이 사진은 실제 외부 하드웨어이며 내부 구조를 표현한 단면도가 아닙니다.')}</p></div>
 <div class="hardware-panel" id="panel-electronics" role="tabpanel" aria-labelledby="tab-electronics" data-hardware-panel="electronics" hidden>${image('rocket-detail.webp',t('Exterior detail of PSI’s rocket; flight electronics sit within the vehicle','PSI 로켓의 외부 모습. 비행 전자장치는 기체 내부에 위치합니다.'),'hardware-detail')}<h3>${t('From measurements to a flight-state estimate','측정에서 비행 상태 추정으로')}</h3><p>${t('The current Arduino Portenta H7 software separates sensor processing and flight decisions on M7 from SD logging and XBee telemetry on M4. Its UKF estimates vertical motion from acceleration and barometric altitude; GNSS supplies a separate position record. An integrated Python ground station supports live inspection and recorded-log playback.','현재 Arduino Portenta H7 소프트웨어는 M7의 센서 처리·비행 판단과 M4의 SD 기록·XBee 원격 측정을 분리합니다. UKF는 가속도와 기압 고도로 수직 운동을 추정하고 GNSS는 별도의 위치 기록을 제공합니다. 통합 Python 지상국에서 실시간 데이터를 확인하거나 저장된 로그를 재생할 수 있습니다.')}</p>${link(sources.avionics,t('Explore the flight software','비행 소프트웨어 살펴보기'))}</div>
 <div class="hardware-panel" id="panel-recovery" role="tabpanel" aria-labelledby="tab-recovery" data-hardware-panel="recovery" hidden>${image('field-team.webp',t('PSI members working with the rocket at the field','현장에서 로켓을 다루는 PSI 구성원들'),'hardware-detail')}<h3>${t('The flight includes the return','돌아오는 것까지가 비행')}</h3><p>${t('Recovery is an engineering objective of its own. The public December 2025 PSLV-II record reports completion of the parachute mission alongside 360-degree onboard filming. Earlier flights and their outcomes remain part of the programme’s learning record.','회수는 독립적인 공학 과제입니다. 2025년 12월 PSLV-II 공개 기록에는 360도 탑재 영상 촬영과 함께 낙하산 임무 완료가 기록되어 있습니다. 이전 비행의 결과도 프로젝트의 학습 기록으로 남습니다.')}</p>${link(sources.flight2,t('Watch the December flight','12월 비행 영상 보기'))}</div>
 </div></div>`;
 const currentResearchIndex=()=>`<section class="wrap current-research-section" id="current-research" aria-labelledby="current-research-heading">
  <div class="current-research-intro"><h2 id="current-research-heading">${t('Current studies','진행 중인 연구')} <span>2026.09</span></h2><p class="current-research-status">${t('Ongoing conference manuscripts; not yet accepted or published.','진행 중인 학회 원고 연구이며 게재 확정·출판 논문은 아닙니다.')}</p></div>
  <div class="current-research-list">${currentResearch.map(r=>`<article id="${r.id}" data-current-research><div class="current-team"><span>${t('Team','연구팀')}</span><strong>${String(r.team).padStart(2,'0')}</strong></div><div class="current-research-copy"><h3>${esc(loc(r.shortTitle))}</h3><p class="current-question">${esc(loc(r.question))}</p><div class="current-stage"><h4>${t('Current stage','현재 단계')}</h4><p>${esc(loc(r.stage))}</p></div><details><summary>${t('Method, next steps & manuscript title','연구 방법, 다음 단계와 원제')}<span aria-hidden="true">+</span></summary><div class="current-research-expanded"><div data-research-method><h4>${t('How the team approaches it','연구 방법')}</h4><p>${esc(loc(r.method))}</p></div><div data-research-next><h4>${t('What comes next','다음 검증 과제')}</h4><p>${esc(loc(r.next))}</p></div><div class="current-manuscript-title"><h4>${t('Working manuscript title','작성 중인 원고의 제목')}</h4><p lang="ko">${esc(r.title.ko)}</p><p lang="en">${esc(r.title.en)}</p></div></div></details></div></article>`).join('')}</div></section>`;
 const currentResearchLinks=()=>`<section class="current-research-links section"><div class="wrap"><div class="section-heading"><div><p class="section-context">${t('Research in progress / September 2026','진행 중인 연구 / 2026년 9월')}</p><h2>${t('Five teams,<br>five open questions.','다섯 팀이 탐구하는<br>다섯 가지 질문.')}</h2></div><p>${t('From separation dynamics to tail-fin control, the current manuscripts connect models, prototypes and planned experiments. Explore each study’s method, present limits and next validation step.','분리 동역학부터 테일핀 제어까지, 현재 연구는 모델과 시제품, 앞으로의 실험을 연결합니다. 각 연구의 방법과 현재 한계, 다음 검증 과제를 살펴보세요.')}</p></div><ol>${currentResearch.map(r=>`<li><a href="research.html#${r.id}"><span>${t('Team','연구팀')} ${String(r.team).padStart(2,'0')}</span><strong>${esc(loc(r.shortTitle))}</strong><span aria-hidden="true">↗</span></a></li>`).join('')}</ol><p class="small-copy">${t('Ongoing manuscripts; not a list of accepted publications or completed flight demonstrations.','작성 중인 원고 연구입니다. 게재 확정 논문이나 비행 실증 완료 목록이 아닙니다.')}</p></div></section>`;
 const joinBand=()=>`<section class="join-band"><div class="wrap join-band-inner"><h2>${t('There is a place<br>to begin.','처음 배우는 곳에서,<br>함께 만드는 사람으로.')}</h2><div><p>${t('Meet the people, explore an introductory notebook or find the latest recruitment announcement. You do not have to arrive with a finished research idea.','사람들을 만나고, 입문 노트북을 열어 보고, 최신 모집 공지를 확인하세요. 완성된 연구 아이디어가 없어도 배우는 것부터 시작할 수 있습니다.')}</p>${internal('join',t('Find your way into PSI','PSI 참여 안내'),'button')}</div></div></section>`;
 const activities=()=>`<section class="programme-section section" aria-labelledby="activity-heading"><div class="wrap activity-layout" data-activity-selector>
  <div class="activity-navigation"><h2 id="activity-heading">${t('Take part in PSI.','PSI에서 함께하는 일.')}</h2><div class="activity-tabs" data-activity-tabs hidden role="tablist" aria-orientation="vertical" aria-label="${t('Explore PSI activities','PSI 활동 살펴보기')}">${[['projects','Projects','프로젝트'],['research','Research','연구'],['learning','Learning','배움']].map(([id,en,kr],i)=>`<button id="activity-tab-${id}" role="tab" aria-controls="activity-${id}" aria-selected="${i===0}" tabindex="${i===0?'0':'-1'}" data-activity="${id}">${t(en,kr)}</button>`).join('')}</div></div>
  <div class="activity-panels">
   <article class="activity-panel" id="activity-projects" data-activity-panel="projects">
    ${figure('field-team.webp',t('PSI members with their rocket at the launch field','발사 현장에서 로켓과 함께한 PSI 구성원들'),t('Working with the rocket at the field.','현장에서 로켓을 다루는 구성원들.'))}
    <div class="activity-copy"><h3>${t('Build it. Bring it to the field.','직접 만들고, 현장에서 확인합니다.')}</h3><p>${t('The Rocket Team develops solid rockets for NURA activity. The Aircraft Team works on quadrotor and VTOL aircraft, connecting design and fabrication with competition experience.','로켓팀은 NURA 활동을 위한 고체 로켓을 개발합니다. 항공기팀은 쿼드로터와 VTOL 비행체의 설계와 제작을 경진대회 경험으로 연결합니다.')}</p><a class="text-link" data-activity-destination href="projects.html">${t('Explore projects','프로젝트 살펴보기')}</a></div>
   </article>
   <article class="activity-panel activity-research" id="activity-research" data-activity-panel="research">
    <figure><a href="${asset}tms-test-2026-04-08.png" aria-label="${t('Open the full-size thrust graph','추력 그래프 원본 크기로 열기')}">${image('tms-test-2026-04-08-preview.webp',t('Corrected and filtered thrust measurements from the 8 April 2026 test','2026년 4월 8일 시험의 보정된 추력 측정값과 필터링 결과'))}</a><figcaption>${t('One example from the public 8 April 2026 test record: corrected load-cell readings and the filtered thrust trace.','2026년 4월 8일 공개 시험 기록의 한 예: 보정된 로드셀 신호와 필터링한 추력 측정 결과.')} ${link(`${sources.tests}/blob/main/tests/2026-04-08/index.md`,t('Read the test record','시험 기록 읽기'))}</figcaption></figure>
    <div class="activity-copy"><h3>${t('A question, a method, a result.','질문에서 방법으로, 결과로.')}</h3><p>${t('Teams investigate questions in flight-state estimation, injector mixing and aircraft stability through year-long projects. They share methods and results in research meetings, conference posters and presentations.','연구팀은 연간 프로젝트로 비행 상태 추정, 인젝터 혼합, 항공기 안정성 등의 질문을 탐구합니다. 연구 모임과 학회 포스터, 발표를 통해 방법과 결과를 공유합니다.')}</p><a class="text-link" data-activity-destination href="research.html">${t('Explore current research','진행 중인 연구 살펴보기')}</a></div>
   </article>
   <article class="activity-panel" id="activity-learning" data-activity-panel="learning">
    ${figure('team.webp',t('The PSI group wearing club T-shirts','동아리 티셔츠를 입은 PSI 구성원들'),t('The PSI group in club T-shirts.','동아리 티셔츠를 입고 함께한 PSI 구성원들.'))}
    <div class="activity-copy"><h3>${t('Find a place to begin.','함께 배우며 시작합니다.')}</h3><p>${t('Newcomer education, Freshman Research Participation and member seminars offer ways into the work. PSIntelligence provides public notebooks for estimation and rocket-apogee prediction.','신입 교육, 새내기연구참여, 회원 세미나로 활동을 시작할 수 있습니다. PSIntelligence에는 상태 추정과 로켓 최고 고도 예측을 위한 공개 노트북이 준비되어 있습니다.')}</p><a class="text-link" data-activity-destination href="learning.html">${t('Start learning','배움 시작하기')}</a></div>
   </article>
  </div></div></section>`;
 const home=()=>`<section class="opening">${media(true)}</section>
 <section class="wrap section home-rocket"><div class="rocket-story"><p class="section-context">${t('The PSLV programme','PSLV 로켓 프로젝트')}</p><h2>${t('The work behind<br>a few seconds<br>of flight.','짧은 비행을 만드는<br>긴 시간의 연구.')}</h2><p>${t('PSLV stands for POSTECH Science Launch Vehicle. Since its first recorded launch in November 2024, the programme has connected structures, flight electronics, propulsion and recovery in a student-built sounding rocket.','PSLV는 POSTECH Science Launch Vehicle의 약자입니다. 2024년 11월 첫 발사 이후, 학생들이 제작한 사운딩 로켓 안에서 구조, 비행 전자장치, 추진과 회수를 연결해 왔습니다.')}</p><p>${t('In December 2025, the public PSLV-II record reports a completed parachute mission and 360-degree onboard filming. The flight is one moment in a longer cycle of building, testing and learning.','2025년 12월 PSLV-II의 공개 기록에는 낙하산 임무와 360도 탑재 영상 촬영 완료가 담겨 있습니다. 한 번의 비행은 설계하고, 시험하고, 배우는 긴 과정의 한 장면입니다.')}</p>${internal('pslv',t('Explore the vehicle and flight history','비행체와 발사 기록 살펴보기'),'button secondary')}<p class="source-line">${link(sources.article,t('Read the story at POSTECH','POSTECH에서 창립 이야기 읽기'))}</p></div><figure class="rocket-photo">${image('rocket-full.webp',t('Full-length PSI rocket at the launch field','발사 현장에 세워진 PSI 로켓의 전체 모습'))}<figcaption>${t('Student-built hardware, photographed at the launch field.','발사 현장에서 만난 학생들의 하드웨어.')}</figcaption></figure></section>
 ${activities()}
 <section class="wrap current-research-invitation"><div><p class="section-context">${t('Research in progress / 2026','진행 중인 연구 / 2026')}</p><h2>${t('What are we investigating now?','지금, 어떤 질문을 탐구할까요?')}</h2></div><div><p>${t('Five teams are studying separation dynamics, learning-assisted landing, electric thrust vectoring, hybrid injectors and tail-fin control. Read the working methods and the validation still ahead.','다섯 팀이 분리 동역학, 학습 기반 착륙, 전기식 추력 편향, 하이브리드 인젝터와 테일핀 제어를 연구합니다. 현재의 방법과 앞으로의 검증 과제를 만나보세요.')}</p>${internal('research#current-research',t('Explore the five current studies','진행 중인 다섯 연구 보기'),'button secondary')}</div></section>
 <section class="wrap section">${sectionHeading(t('Questions taking shape.','구체적인 질문이 연구로.'),t('A selection from the 2025 conference archive. Original Korean titles and presentation files are available in the full archive.','2025년 학회 발표에서 고른 연구입니다. 전체 아카이브에서 원제와 발표 자료를 확인할 수 있습니다.'))}<div class="research-preview">${[
 ['Flight electronics','비행 전자장치','How can a rocket estimate its motion?','로켓은 자신의 움직임을 어떻게 추정할까?','Kalman-filter sensor fusion combines model predictions with measured signals to study flight-state estimation.','칼만 필터 센서 퓨전으로 모델의 예측과 측정 신호를 연결해 비행 상태 추정을 연구합니다.','ksas-2025-fusion'],
 ['Propulsion research','추진 연구','What changes how an injector mixes?','인젝터의 혼합 성능은 무엇이 바꿀까?','Swirl-injector studies compare mixing behaviour at different pressure-drop ratios.','스월 인젝터 연구에서는 압력 강하 비율에 따른 혼합 거동을 비교합니다.','kspe-2025-plif'],
 ['Aircraft research','항공기 연구','How does a small surface change flight?','작은 표면 변화가 비행에 주는 영향은?','Vortex-generator research examines the stability of small aircraft in high-speed flight.','보텍스 생성기 연구는 소형 비행체의 고속 비행 안정성을 살펴봅니다.','ksas-2025-vortex']
 ].map(([en,kr,title,kTitle,body,kBody,id])=>`<article><p class="section-context">${t(en,kr)} / 2025</p><h3>${t(title,kTitle)}</h3><p>${t(body,kBody)}</p>${link(`research.html#${id}`,t('View research record','연구 기록 보기'))}</article>`).join('')}</div></section>
 <section class="testing-feature"><div class="wrap section"><div class="testing-intro"><div><p class="section-context">${t('Public test archive / 2026','공개 시험 아카이브 / 2026')}</p><h2>${t('What happened<br>on the test stand.','시험대 위에서<br>무슨 일이 있었을까.')}</h2></div><div><p>${t('Measurements matter most with their context. PSI’s public records include thrust and pressure data, plots, processed measurements and the issues observed during each test.','측정값은 시험의 맥락과 함께 볼 때 의미가 있습니다. PSI 공개 기록에는 추력·압력 데이터, 그래프, 처리된 측정값과 시험 중 관찰한 문제가 담겨 있습니다.')}</p>${link(sources.tests,t('Open the test archive','시험 아카이브 열기'))}</div></div>${testPlot()}<div class="test-date-strip">${tests.map(test=>`<a href="${test.url}"><time datetime="${test.date}">${test.date}</time><span>${t('Data & test notes','데이터와 시험 노트')}</span></a>`).join('')}</div><p class="small-copy">${t('Published 2026 test records. The July record notes pressure-channel anomalies; the April 3 record documents several test issues. The archive preserves those limitations alongside the results.','2026년 공개 시험 기록입니다. 7월 기록에는 압력 채널 이상, 4월 3일 기록에는 여러 시험 문제가 남아 있습니다. 결과와 함께 한계도 기록합니다.')}</p></div></section>
 <section class="wrap section learning-feature"><div><p class="section-context">${t('Learn with PSIntelligence','PSIntelligence로 배우기')}</p><h2>${t('A notebook is<br>a good place to start.','노트북 하나에서<br>시작하는 비행 연구.')}</h2><p>${t('How do you estimate a rocket’s altitude from noisy measurements? The PSIntelligence 101 resource starts with probability and Kalman filtering, then explores EKF/UKF, physics-informed models and uncertainty.','잡음이 섞인 측정값으로 로켓의 고도를 어떻게 추정할까요? PSIntelligence 101은 확률과 칼만 필터에서 시작해 EKF/UKF, 물리 기반 모델, 불확실성을 탐구합니다.')}</p>${internal('learning',t('Explore learning at PSI','PSI의 교육 살펴보기'),'button secondary')}</div><div class="learning-topics" aria-label="${t('PSIntelligence study topics','PSIntelligence 학습 주제')}"><p>${t('Measurements','측정')}</p><span aria-hidden="true">↓</span><p>${t('Models & estimation','모델과 추정')}</p><span aria-hidden="true">↓</span><p>${t('Prediction & uncertainty','예측과 불확실성')}</p><div>${link(sources.learning,t('Open PSIntelligence 101','PSIntelligence 101 열기'))}</div></div></section>
 <section class="community-section">${figure('team.webp',t('PSI members together in the laboratory','실험실에서 함께한 PSI 구성원들'),t('PSI members together in the laboratory.','실험실에서 함께한 PSI 구성원들.'),'community-photo')}<div class="wrap community-copy"><h2>${t('The people<br>behind the rocket.','로켓 뒤에 있는<br>사람들.')}</h2><div><p>${t('PSI grew from students preparing a programme in 2023 to a group founded in February 2024. Today, research, competition teams and the people supporting their work share the same student-led home.','2023년 학생들의 준비에서 출발해 2024년 2월 창립한 PSI. 연구팀과 경진대회팀, 그 활동을 뒷받침하는 구성원들이 학생 중심의 공동체를 함께 만들어 갑니다.')}</p>${internal('about',t('Meet PSI','PSI 알아보기'))}</div></div></section>${joinBand()}`;
 const projects=()=>`${pageHead(t('Projects.','프로젝트.'),t('Rockets, aircraft and the systems that make an experiment useful. Explore programme histories, current public software and five ongoing research studies.','로켓과 항공기, 그리고 실험을 의미 있게 만드는 시스템. 프로젝트의 기록, 현재 공개 소프트웨어와 진행 중인 다섯 연구를 살펴보세요.'))}
 <section class="wrap project-feature">${figure('field-team.webp',t('PSI team working beside the rocket at the launch field','발사 현장에서 로켓과 함께 작업하는 PSI 팀'),t('PSI members and hardware at the field.','현장의 PSI 구성원과 하드웨어.'))}<div><p class="section-context">${t('Rocket programme','로켓 프로젝트')}</p><h2>PSLV</h2><p class="large-copy">POSTECH Science Launch Vehicle</p><p>${t('The PSLV programme connects the entire sounding-rocket workflow: vehicle construction, avionics integration, launch and recovery. Its public record includes the first-generation November 2024 flight, an August 2025 avionics flight and PSLV-II in December 2025.','PSLV 프로젝트는 비행체 제작, 에비오닉스 통합, 발사와 회수를 연결합니다. 공개 기록에는 2024년 11월 1세대 발사, 2025년 8월 에비오닉스 비행, 같은 해 12월 PSLV-II가 담겨 있습니다.')}</p>${internal('pslv',t('Explore PSLV','PSLV 자세히 보기'),'button')}</div></section>
 <section class="wrap section engineering-project" id="avionics"><div class="project-heading"><p class="section-context">${t('Flight electronics / public source','비행 전자장치 / 공개 소스')}</p><h2>${t('Avionics','에비오닉스')}</h2><p class="large-copy">${t('Two cores.<br>One flight record.','두 개의 코어에서<br>하나의 비행 기록으로.')}</p>${link(sources.avionics,t('Explore the Avionics source','Avionics 소스 살펴보기'),'button secondary')}<p class="source-line">${t('Source revision','소스 버전')} <code>7cfb5be0</code><br>${t('Checked 17 September 2026','2026년 9월 17일 확인')}</p></div><div class="project-details"><p>${t('PSI’s current flight computer divides work between the two cores of the Arduino Portenta H7. Sensor processing and flight decisions stay on M7, while M4 handles SD logging and the XBee telemetry path. The separation keeps a durable onboard record alongside the data sent to the ground.','PSI의 현재 비행 컴퓨터는 Arduino Portenta H7의 두 코어에 작업을 나눕니다. M7은 센서 처리와 비행 판단을, M4는 SD 기록과 XBee 원격 측정 경로를 담당합니다. 지상으로 전송하는 데이터와 함께 기체 내부에도 기록을 남기는 구조입니다.')}</p>
  <dl class="core-responsibilities"><div><dt>M7</dt><dd><strong>${t('Flight loop · configured 100 Hz','비행 루프 · 설정 주기 100 Hz')}</strong><p>${t('Sensor acquisition, vertical-state estimation, flight-state and recovery decisions.','센서 수집, 수직 상태 추정, 비행 상태와 회수 판단을 담당합니다.')}</p></dd></div><div><dt>M4</dt><dd><strong>${t('Logging & telemetry · configured 25 Hz transmission','기록과 원격 측정 · 전송 설정 주기 25 Hz')}</strong><p>${t('Decimated XBee transmission with a separate SD-writer thread for storage.','간추린 데이터를 XBee로 전송하며 별도 SD 기록 스레드로 저장합니다.')}</p></dd></div></dl>
  <div class="technical-block"><h3>${t('Estimate the vertical motion','수직 운동 상태 추정')}</h3><p>${t('The unscented Kalman filter (UKF) combines global-Z acceleration from the IMU with barometric altitude, updating at approximately 50 Hz when fresh barometric samples arrive. GNSS supports position recording and recovery; it is not an input to this vertical-state UKF or the flight-state decision path.','무향 칼만 필터(UKF)는 IMU의 전역 Z축 가속도와 기압 고도를 결합하며, 새로운 기압 샘플이 들어올 때 약 50 Hz로 갱신합니다. GNSS는 위치 기록과 회수에 활용하며, 이 수직 상태 UKF나 비행 상태 판단 경로의 입력은 아닙니다.')}</p><p class="small-copy">${t('The rates above describe the configured software cadence, not a measured end-to-end performance guarantee.','위 주기는 소프트웨어 설정 기준이며 전체 시스템의 실측 성능을 보장하는 수치가 아닙니다.')}</p>${link(sources.flightSoftware,t('Read the flight-computer guide','비행 컴퓨터 안내 읽기'))}</div>
  <div class="technical-block"><h3>${t('An integrated ground station','통합 지상국')}</h3><p>${t('The current Python interface brings 3D attitude, position history and flight measurements into one dashboard. Available plots cover acceleration, angular rate, altitude, vertical velocity and predicted apogee; acceleration and altitude are the default visible plots. A grid or offline map provides context for the recorded positions.','현재 Python 인터페이스는 3D 자세, 위치 이력과 비행 측정값을 하나의 대시보드에 모읍니다. 가속도, 각속도, 고도, 수직 속도, 예측 최고 고도 그래프를 제공하며 기본 화면에는 가속도와 고도 그래프가 표시됩니다. 위치 이력은 격자 또는 오프라인 지도와 함께 살펴볼 수 있습니다.')}</p><p>${t('Flight statistics, sensor freshness, telemetry and system logs sit alongside recorded-log playback. Opening a log, pausing, seeking and replaying at 1–50× speed support post-test inspection. A sensor-health indicator describes incoming data freshness, not a guarantee of a GNSS fix or flight readiness.','비행 통계, 센서 데이터 갱신 상태, 텔레메트리와 시스템 로그를 기록 재생 기능과 함께 제공합니다. 로그를 열고 일시 정지하거나 위치를 이동하고 1–50배속으로 재생하며 시험 후 데이터를 검토합니다. 센서 상태 표시는 수신 데이터의 최신성을 나타내며 GNSS 위치 확정이나 비행 준비 상태를 보장하지 않습니다.')}</p>${link(sources.groundStation,t('Read the ground-station guide','지상국 안내 읽기'))}</div><p class="small-copy">${t('These are capabilities of the cited public revision, not evidence that every feature flew on a particular mission.','인용한 공개 소스 버전의 기능이며, 모든 기능이 특정 임무에 탑재되었다는 근거는 아닙니다.')}</p>${link('research.html#ksas-2025-fusion',t('Related 2025 sensor-fusion research','관련 2025년 센서 퓨전 연구'))}</div></section>
 <section class="test-project section" id="tms"><div class="wrap engineering-project"><div class="project-heading"><p class="section-context">${t('Ground testing / public source','지상 시험 / 공개 소스')}</p><h2>${t('Thrust Measurement<br>System','추력 측정<br>시스템')}</h2><p class="large-copy">${t('From a force<br>to a useful record.','힘을 측정해,<br>연구 기록으로.')}</p>${link(sources.tms,t('Explore the TMS repository','TMS 저장소 살펴보기'),'button secondary')}</div><div class="project-details"><p>${t('The Thrust Measurement System (TMS) connects instrumented ground testing to calibration, logs and analysis. Its value is the traceable route from a sensor signal to a measurement that can be inspected.','추력 측정 시스템(TMS)은 계측 장치를 사용한 지상 시험을 교정, 기록, 분석으로 연결합니다. 센서 신호가 검토 가능한 측정값이 되는 과정을 추적할 수 있도록 합니다.')}</p><div class="technical-block"><h3>${t('Acquisition and storage','데이터 수집과 저장')}</h3><p>${t('An Arduino Nano reads load-cell and pressure signals through two ADS1115 channels and stores measurements on an SD card. The acquisition code configures 320 samples per second; that is distinct from the ADC’s conversion-rate setting.','Arduino Nano가 두 ADS1115 채널을 통해 로드셀과 압력 신호를 읽고 SD 카드에 측정값을 저장합니다. 수집 코드는 초당 320개 샘플로 설정되어 있으며, 이는 ADC 자체의 변환 속도 설정과 구분됩니다.')}</p></div><div class="technical-block"><h3>${t('Calibration and interpretation','교정과 해석')}</h3><p>${t('Python tools support calibration, filtering and thrust/impulse analysis. The public test archive keeps plots and experiment notes beside processed data, including instrument anomalies and other limitations.','Python 도구로 교정, 필터링, 추력과 충격량 분석을 수행합니다. 공개 시험 아카이브에는 처리된 데이터와 함께 그래프, 실험 노트, 계측 이상과 한계가 남아 있습니다.')}</p></div>${link(sources.tests,t('Read the 2026 test records','2026년 시험 기록 읽기'))}</div></div>${testPlot(true)}</section>
 <section class="wrap section split-content"><div><p class="section-context">${t('Aircraft programme','항공기 프로젝트')}</p><h2>${t('More than<br>a rocket team.','로켓을 넘어,<br>항공기로.')}</h2></div><div><p class="large-copy">${t('The Aircraft Team designs and fabricates quadrotor and VTOL aircraft for competition activity.','항공기팀은 경진대회 활동을 위해 쿼드로터와 VTOL 비행체를 설계하고 제작합니다.')}</p><p>${t('The research archive also asks how vortex generators affect flight stability and how mesostructures relate to the behaviour of small aircraft. These historical studies and current programme descriptions are different parts of the same broader interest in flight.','연구 아카이브에는 보텍스 생성기가 비행 안정성에 주는 영향과 메조구조가 소형 비행체의 거동에 주는 영향을 다룬 연구도 있습니다. 과거 연구와 현재 활동은 비행을 탐구하는 서로 다른 방식입니다.')}</p><p>${t('The current precision-landing study combines a conventional controller with PPO-based residual corrections. It is a simulation feasibility study, with real-flight validation still ahead.','현재 정밀 착륙 연구는 기존 제어기와 PPO 기반 잔차 보정을 결합합니다. 시뮬레이션으로 가능성을 검토하는 단계이며 실제 비행 검증은 앞으로의 과제입니다.')}</p>${link('research.html#ksas-2025-vortex',t('Read the aircraft research','항공기 연구 읽기'))}</div></section>
 ${currentResearchLinks()}<section class="wrap project-resources"><div class="related-resources"><h3>${t('Related public development resources','관련 공개 개발 자료')}</h3><p>${t('The motor repository describes development for PSLV. The TVC resources document simulation and control-development tools, including ROS2, Gazebo and PX4; they do not establish a demonstrated reusable vehicle.','모터 저장소는 PSLV를 위한 개발 목적을 설명합니다. TVC 자료에는 ROS2, Gazebo, PX4를 포함한 시뮬레이션과 제어 개발 환경이 담겨 있으며 재사용 비행체의 실증을 의미하지 않습니다.')}</p><div class="link-row">${link(sources.motor,t('Solid Rocket Motor','고체 로켓 모터'))}${link(sources.tvc,t('TVC testbed','TVC 테스트베드'))}${link(sources.tvcData,t('TVC data','TVC 데이터'))}</div></div></section>${joinBand()}`;
 const pslv=()=>`${pageHead(t('PSLV.<br>A student-built<br>launch vehicle.','PSLV.<br>학생이 만드는<br>발사체.'),t('POSTECH Science Launch Vehicle brings structures, electronics, propulsion and recovery into one sounding-rocket programme. Here is the hardware and the public record behind its flights.','POSTECH Science Launch Vehicle은 구조, 전자장치, 추진과 회수를 하나로 연결하는 사운딩 로켓 프로젝트입니다. 실제 하드웨어와 비행의 공개 기록을 만나보세요.'),`<div class="link-row"><a class="text-link" href="#vehicle">${t('Explore the vehicle','비행체 살펴보기')}</a><a class="text-link" href="#flights">${t('Flight history','비행 기록')}</a></div>`)}<section class="wrap" aria-label="${t('Launch and onboard footage','발사와 탑재 영상')}">${media()}</section><section class="wrap section" id="vehicle">${hardware()}</section><section class="ledger-section section" id="flights"><div class="wrap">${sectionHeading(t('A record of real flights.','실제 비행의 기록.'),t('Three dated milestones in the public PSI timeline. A launch, a recovery and a research result each describe a different outcome.','PSI 공개 연혁에서 확인한 세 차례의 비행 기록입니다. 발사, 회수, 연구 성과는 각각 다른 결과를 설명합니다.'))}${flightLedger()}</div></section><section class="wrap section split-content"><div><h2>${t('The work<br>between flights.','비행과 비행 사이에<br>계속되는 연구.')}</h2></div><div><p>${t('Flight electronics, structures and measurement systems develop alongside the vehicle. The public project repositories make that work accessible, while conference records explain specific questions such as sensor fusion and stage-separation stability.','비행 전자장치, 구조와 측정 시스템은 비행체와 함께 발전합니다. 공개 프로젝트 저장소에서 개발 내용을 살펴볼 수 있으며, 학회 기록에서는 센서 퓨전이나 단 분리 안정성과 같은 구체적인 질문을 만날 수 있습니다.')}</p><div class="resource-list">${internal('projects#avionics',t('Flight electronics and ground-station software','비행 전자장치와 지상국 소프트웨어'))}${link('projects.html#tms',t('Thrust Measurement System','추력 측정 시스템'))}${link('research.html#ksas-2025-separation',t('Stage-separation research','단 분리 연구'))}${link(sources.article,t('The founder’s account on POSTECH','POSTECH에 실린 창립자의 이야기'))}</div></div></section>${joinBand()}`;
 const researchPage=()=>`${pageHead(t('Research.','연구.'),t('From an open question to a model, a prototype and the next experiment. Meet five current research teams, then explore the conference and award records that came before.','하나의 질문에서 모델과 시제품, 다음 실험으로. 지금 연구팀이 탐구하는 다섯 주제와 이전 학회 발표·수상 기록을 만나보세요.'),`<div class="link-row"><a class="text-link" href="#current-research">${t('Current research','진행 중인 연구')}</a><a class="text-link" href="#research-archive">${t('Historical records','이전 연구 기록')}</a></div>`)}${currentResearchIndex()}<section class="archive-section section" id="research-archive" data-research-archive><div class="wrap">${sectionHeading(t('The research archive.','연구 아카이브.'),t('Nine conference records and six UGRP award records from the 2024–2025 research years, preserved with their original titles and public sources. These historical records are separate from the ongoing manuscripts above.','2024–2025년 연구의 학회 기록 9건과 UGRP 수상 기록 6건을 원제와 공개 출처로 보존했습니다. 위의 진행 중인 원고 연구와 구분되는 이전 활동 기록입니다.'))}<form class="research-filters" aria-label="${t('Filter research records','연구 기록 필터')}"><label>${t('Topic','주제')}<select data-filter-topic><option value="all">${t('All topics','모든 주제')}</option>${Object.entries(topicLabels).map(([key,label])=>`<option value="${key}">${loc(label)}</option>`).join('')}</select></label><label>${t('Record type','기록 유형')}<select data-filter-type><option value="all">${t('All records','모든 기록')}</option><option value="conference">${t('Conference','학회 발표')}</option><option value="award">${t('UGRP award','UGRP 수상')}</option></select></label><label class="search-label">${t('Search titles','제목 검색')}<input type="search" data-filter-search placeholder="${t('Try sensor fusion','센서 퓨전 검색')}" autocomplete="off"></label><button class="button secondary filter-reset" type="reset" data-filter-reset>${t('Reset','초기화')}</button></form><div class="archive-count"><p data-result-count role="status" aria-live="polite">${t('15 records','15개 기록')}</p><p>${t('English descriptions are editorial translations. Original Korean titles are preserved.','한국어 원제를 보존했습니다. 영어 설명은 편집 번역입니다.')}</p></div><div class="research-records">${research.map(r=>`<article class="research-record" id="${r.id}" data-research-item data-topic="${r.topic}" data-type="${r.type}" data-search="${esc(`${r.title} ${r.english} ${r.venue}`.toLowerCase())}"><div class="research-meta"><span>${r.year} ${r.venue}</span><span>${loc(r.form)}</span><span class="topic-tag">${loc(topicLabels[r.topic])}</span></div><div><h3 lang="ko">${r.title}</h3>${!ko?`<p class="translation">${esc(r.english)}</p>`:''}${r.type==='award'?`<p class="small-copy">${t('Research-year label; the topic is abbreviated from the public awards register.','연구 연도 기준이며 공개 수상 목록의 주제를 요약했습니다.')}</p>`:''}${link(r.url,r.type==='award'?t('View awards register','수상 목록 보기'):t('Open original document','원문 자료 열기'))}</div></article>`).join('')}</div><div class="no-results" data-no-results hidden><h2>${t('No records match these filters.','조건에 맞는 기록이 없습니다.')}</h2><p>${t('Try a different topic or reset the filters to see all records.','다른 주제를 선택하거나 필터를 초기화해 전체 기록을 확인하세요.')}</p></div><p class="archive-note">${t('Conference document titles and public links are preserved from PSI’s research register. UGRP entries describe awarded research topics; they are not additional conference papers. Research years and award ceremony dates are listed separately.','학회 자료의 원제와 공개 링크는 PSI 연구 목록을 따릅니다. UGRP 항목은 수상한 연구 주제로, 추가 학회 논문을 의미하지 않습니다. 연구 연도와 수상 행사 날짜를 구분해 표시했습니다.')}</p></div></section><section class="wrap section split-content"><h2>${t('A question becomes<br>a year of work.','하나의 질문이<br>일 년의 연구로.')}</h2><div><p>${t('Research teams form around year-long projects, give progress updates and prepare conference presentations. New members first take part in learning and group activity; joining a research team is a further step, not an automatic assignment.','연구팀은 연간 프로젝트를 중심으로 구성되어 진행 상황을 공유하고 학회 발표를 준비합니다. 신입 회원은 먼저 교육과 활동에 참여하며, 연구팀 합류는 자동 배정과 구분되는 다음 단계입니다.')}</p>${internal('join',t('Learn about joining PSI','PSI 참여 안내 보기'))}</div></section>`;
 const learning=()=>`${pageHead(t('Learning at PSI.','PSI에서 배우기.'),t('You can begin with a notebook, a seminar or a practical session. PSI connects learning with the real questions its research and competition teams encounter.','노트북, 세미나, 실습에서 시작할 수 있습니다. PSI는 연구팀과 경진대회팀이 마주하는 실제 질문을 배움으로 연결합니다.'))}<section class="learning-banner"><div class="wrap split-content"><h2>${t('You do not need<br>to know it all<br>on day one.','첫날부터<br>모든 것을 알<br>필요는 없습니다.')}</h2><div><p class="large-copy">${t('Learn the language of the project, take part in practical work and build toward a question of your own.','프로젝트의 언어를 익히고, 실습에 참여하며, 자신의 질문을 찾아가세요.')}</p><p>${t('The Education department prepares newcomer learning and practical materials, supports Freshman Research Participation, and organises internal seminars. Learning takes place alongside the people building the systems.','교육부는 신입 교육과 실습 자료를 준비하고, 새내기연구참여를 지원하며 내부 세미나를 운영합니다. 시스템을 만드는 사람들과 함께 배웁니다.')}</p></div></div></section><section class="wrap section"><div class="section-heading"><div><p class="section-context">${t('Public learning resource','공개 학습 자료')}</p><h2>PSIntelligence 101</h2></div><div><p>${t('An educational pipeline for rocket-apogee prediction, from probability and filtering to models, uncertainty and onboard deployment. The notebooks are a starting point for study; they do not establish flight qualification.','확률과 필터에서 모델, 불확실성, 탑재 구현까지 이어지는 로켓 최고 고도 예측 교육 자료입니다. 학습의 출발점이며 비행 적합성이 검증되었다는 의미는 아닙니다.')}</p>${link(sources.learning,t('Open the notebooks','학습 노트북 열기'),'button secondary')}</div></div><div class="curriculum">${curriculum.map((c,i)=>`<article><span class="step-number">${i+1}</span><div><h3>${loc(c.title)}</h3><p>${loc(c.body)}</p></div></article>`).join('')}</div></section><section class="learning-meetings section"><div class="wrap">${sectionHeading(t('Learning has a place<br>in the week.','함께 모여 배우고,<br>함께 준비합니다.'),t('General meetings and research meetings serve different purposes. For the current calendar and meeting location, follow the group’s announcements.','정기 모임과 연구 모임은 서로 다른 역할을 합니다. 현재 일정과 장소는 연구회 공지를 확인해 주세요.'))}<div class="two-columns"><article><h3>${t('Member seminars & preparation','회원 세미나와 활동 준비')}</h3><p>${t('Members introduce interests, projects and papers. General meetings also support preparation for launch activity, making space to connect a technical topic with the work ahead.','회원들이 관심 주제, 프로젝트, 논문을 소개합니다. 정기 모임에서는 발사 활동을 준비하며 기술적 주제를 앞으로의 작업과 연결합니다.')}</p></article><article><h3>${t('Research progress & discussion','연구 진행 발표와 토론')}</h3><p>${t('Research teams share progress and prepare for conference presentations. Listening to how a team explains its assumptions, methods and results is part of learning how research works.','연구팀이 진행 상황을 공유하고 학회 발표를 준비합니다. 팀이 가정, 방법, 결과를 어떻게 설명하는지 듣는 것도 연구를 배우는 과정입니다.')}</p></article></div></div></section><section class="wrap section split-content"><h2>${t('Coursework that<br>meets hardware.','교과목에서 배운 것을<br>하드웨어로.')}</h2><div><p>${t('PSI’s conference archive contains work on linking rocket-engineering coursework with an aerospace club and on using CFD flow visualisation for education. These are concrete examples of teaching and student projects informing one another.','PSI의 학회 기록에는 로켓공학 교과목과 항공우주동아리의 연계 교육 모델, CFD 유동 시각화를 활용한 교육 연구가 있습니다. 수업과 학생 프로젝트가 서로 영향을 주는 구체적인 사례입니다.')}</p><div class="resource-list">${link('research.html#ksme-2025-model',t('Coursework and aerospace-club education model','교과목·항공우주동아리 연계 교육 모델'))}${link('research.html#ksme-2025-cfd',t('CFD visualisation for aerospace education','CFD 시각화를 활용한 항공우주 교육'))}${link('research.html#kspe-2025-coursework',t('Small-rocket development through coursework','교과목과 연계한 소형 로켓 개발'))}</div></div></section>${joinBand()}`;
 const about=()=>`${pageHead(t('About PSI.','PSI 소개.'),t('PSI is a student aerospace research group in POSTECH Mechanical Engineering. We bring together rocket and aircraft projects, year-long research and the education that helps students take part.','PSI는 포스텍 기계공학과의 학생 항공우주연구회입니다. 로켓과 항공기 프로젝트, 연간 연구, 학생들의 참여를 돕는 교육을 함께 이어 갑니다.'))}${figure('team.webp',t('PSI members together in the laboratory','실험실에서 함께한 PSI 구성원들'),t('PSI members together in the laboratory.','실험실에서 함께한 PSI 구성원들.'),'wrap about-team')}<section class="wrap section origin"><div>${image('founder.webp',t('Photograph accompanying the PSI founder’s POSTECH story','PSI 창립자의 POSTECH 기고에 실린 사진'),'founder-photo')}</div><div><p class="section-context">${t('How PSI began','PSI의 시작')}</p><h2>${t('An idea that<br>became a group.','아이디어가 모여<br>연구회가 되기까지.')}</h2><p>${t('Students began preparing the programme in 2023. PSI’s organisation record gives 20 February 2024 as its founding date; the group adopted its present research-group name in 2025. These are different steps in the same origin story.','2023년 학생들이 활동을 준비하기 시작했습니다. PSI의 조직 기록에 따른 창립일은 2024년 2월 20일이며, 2025년 현재의 연구회 명칭을 사용하게 되었습니다. 하나의 시작을 이루는 서로 다른 단계입니다.')}</p><p>${t('The founder’s first-person account, published by POSTECH in May 2026, describes how students brought the programme together. Read it for the people and decisions behind the launch record.','2026년 5월 POSTECH에 실린 창립자의 기고에는 학생들이 어떻게 프로젝트를 만들어 왔는지 담겨 있습니다. 발사 기록 뒤에 있는 사람과 선택의 이야기를 읽어 보세요.')}</p>${link(sources.article,t('Read the founder’s story','창립자의 이야기 읽기'))}</div></section><section class="organisation-section section"><div class="wrap">${sectionHeading(t('How the work is organised.','활동을 함께 만드는 구조.'),t('Research and competition activity are supported by people who maintain equipment, coordinate resources, communicate the work and help newcomers learn.','장비를 관리하고, 자원을 조율하고, 활동을 알리고, 신입 회원의 배움을 돕는 사람들이 연구와 경진대회 활동을 뒷받침합니다.'))}<div class="org-primary"><article><h3>${t('Research division','연구부')}</h3><p>${t('Five research teams are described in the September 2026 introduction. Teams work through the year, report progress and prepare conference presentations.','2026년 9월 소개 자료에는 다섯 연구팀이 기록되어 있습니다. 연간 연구를 진행하고 진행 상황을 공유하며 학회 발표를 준비합니다.')}</p></article><article><h3>${t('Competition teams','경진대회팀')}</h3><p>${t('The Rocket Team develops and launches solid rockets for NURA activity. The Aircraft Team works on the design and fabrication of quadrotor and VTOL aircraft.','로켓팀은 NURA 활동을 위한 고체 로켓을 개발하고 발사합니다. 항공기팀은 쿼드로터와 VTOL 비행체를 설계하고 제작합니다.')}</p></article></div><div class="org-support">${[[t('Equipment & workspace','장비·사무'),t('Equipment, workspace and documentation for competitions, conferences and launches.','장비와 작업 공간, 경진대회·학회·발사 활동을 위한 문서를 관리합니다.')],[t('Resource coordination','자원 조율'),t('Coordination of the resources that teams need to carry out their work.','각 팀이 활동에 필요한 자원을 조율합니다.')],[t('Communication & community','홍보·기획'),t('Activity stories, recruitment announcements, member events and connections.','활동 소식, 모집 공지, 회원 행사와 교류를 준비합니다.')],[t('Education','교육'),t('Newcomer learning, Freshman Research Participation and internal seminars.','신입 교육, 새내기연구참여, 내부 세미나를 지원합니다.')]].map(([title,body])=>`<article><h4>${title}</h4><p>${body}</p></article>`).join('')}</div></div></section><section class="wrap section leadership"><div><h2>${t('People & guidance.','함께 이끄는 사람들.')}</h2><p>${t('Publicly listed by PSI; checked 17 September 2026. These are the roles shown in the public directory.','PSI 공개 소개에 기재된 역할이며 2026년 9월 17일 확인했습니다.')}</p></div><dl>${[[t('President','회장'),'Uikang Joo'],[t('NURA team leader','NURA 팀장'),'Dain Son'],[t('Secretary','총무'),'Jaeyung Park'],[t('Faculty advisor','지도교수'),'Jin-Tae Kim']].map(([role,name])=>`<div><dt>${role}</dt><dd>${name}</dd></div>`).join('')}<div><dt>${t('Former presidents','역대 회장')}</dt><dd>Un-Seong Baik <small>2025</small><br>Minsoo Kim <small>2024</small></dd></div></dl></section><section class="wrap award-feature">${figure('award.webp',t('PSI group photograph commemorating a POSTECH award','POSTECH 수상을 기념하는 PSI 단체 사진'),t('2 December 2025. Award commemorative group photograph.','2025년 12월 2일. 수상 기념 단체 사진.'))}<div><h2>${t('A history still<br>being written.','계속 쌓여 가는<br>우리의 기록.')}</h2><ul class="short-history"><li><time>2023</time><span>${t('Students begin preparations.','학생들이 준비를 시작합니다.')}</span></li><li><time>2024</time><span>${t('PSI is founded; PSLV-I records its first launch.','PSI 창립, PSLV-I 첫 발사.')}</span></li><li><time>2025</time><span>${t('The research-group name, conference work and PSLV-II recovery mission.','연구회 명칭 정립, 학회 발표, PSLV-II 회수 임무.')}</span></li><li><time>2026</time><span>${t('UGRP recognition and public propulsion-test records.','UGRP 수상과 추진 시험 공개 기록.')}</span></li></ul>${internal('news',t('Browse the dated records','날짜별 기록 살펴보기'))}</div></section><section class="wrap section support-section"><h2>${t('Institutional support.','기관의 지원.')}</h2><div><h3>${t('Listed support','공개된 지원')}</h3><p>${t('The public register lists POSTECH Mechanical Engineering support from 2024 onward.','공개 목록에는 2024년부터의 POSTECH 기계공학과 지원이 기재되어 있습니다.')}</p><h3>${t('Past programmes','과거 지원 사업')}</h3><p>${t('APEC–APRU and LINC 2.0 are listed as completed support for 2024–2025. These are historical programmes, not current commercial sponsorships.','APEC–APRU와 LINC 2.0은 2024–2025년 종료된 지원 사업으로 기재되어 있습니다. 과거 지원이며 현재의 상업 후원을 뜻하지 않습니다.')}</p>${link(sources.legacy,t('View PSI’s public introduction','PSI 공개 소개 보기'))}</div></section>${joinBand()}`;
 const newsPage=()=>`${pageHead(t('News & records.','소식과 기록.'),t('Flights, conference work, research awards and open test records. Dates connect each story to what was actually recorded.','비행, 학회 발표, 연구 수상과 공개 시험 기록. 각 이야기를 실제 기록된 날짜와 함께 모았습니다.'))}<section class="wrap tests-section" id="tests">${sectionHeading(t('2026 propulsion test records','2026년 추진 시험 기록'),t('Measurements as reported by PSI. These experiments do not necessarily share the same test conditions, and the accompanying notes matter.','PSI가 보고한 측정값입니다. 각 실험의 조건이 같다고 가정할 수 없으며, 함께 기록한 시험 노트를 확인해야 합니다.'))}${testTable()}</section><section class="wrap section news-section">${sectionHeading(t('Flights, research & milestones','비행, 연구, 그리고 이정표'))}<div class="news-list">${news.map(n=>`<article><div><time datetime="${n.date}">${n.date}</time><span class="news-kind">${loc(n.kind)}</span></div><div><h3>${loc(n.title)}</h3><p>${loc(n.body)}</p>${link(n.url,t('Read the original record','원본 기록 읽기'))}</div></article>`).join('')}</div></section><section class="wrap section split-content"><h2>${t('Follow the<br>next chapter.','다음 이야기도<br>함께 보세요.')}</h2><div><p>${t('For activity photographs and current announcements, follow PSI’s public channels. Repository records provide a more detailed view of software and test activity.','활동 사진과 현재 공지는 PSI 공개 채널에서 확인하세요. 저장소에서는 소프트웨어와 시험 활동을 더 자세히 살펴볼 수 있습니다.')}</p><div class="link-row">${link(sources.instagram,t('PSI on Instagram','PSI 인스타그램'))}${link(sources.github,t('PSI on GitHub','PSI GitHub'))}</div></div></section>`;
 const join=()=>`${pageHead(t('Join PSI.','PSI와 함께하기.'),t('Start by getting to know the work and the people. Recruitment announcements explain the current eligibility, application route and timing.','활동과 사람들을 알아보는 것부터 시작하세요. 현재 지원 자격, 지원 방법과 일정은 모집 공지에서 확인할 수 있습니다.'))}<section class="wrap join-intro"><div class="recruitment-notice"><h2>${t('Check the latest<br>recruitment announcement.','최신 모집 공지를<br>확인해 주세요.')}</h2><p>${t('For current openings, eligibility, dates and introductory requirements, see the latest recruitment notice on PSI’s official channels.','현재 모집 여부, 지원 자격, 일정과 입문 요건은 PSI 공식 채널의 최신 모집 공지를 확인해 주세요.')}</p>${link(sources.instagram,t('Visit PSI’s announcements','PSI 모집·활동 공지 보기'),'button')}<p class="small-copy">${t('Recruitment schedules are announced for each round.','모집 일정은 차수별로 공지됩니다.')}</p></div>${figure('field-team.webp',t('PSI members and their rocket at the launch field','발사 현장에서 로켓과 함께한 PSI 구성원들'),t('There is work to share before, during and after a flight.','비행 전에도, 현장에서도, 비행 후에도 함께할 일이 있습니다.'))}</section><section class="wrap section">${sectionHeading(t('A way into the work.','활동에 참여하는 과정.'),t('Explore the work, meet the group and build experience. See the current recruitment notice for eligibility and course requirements.','활동을 살펴보고 사람들을 만나며 경험을 쌓아 갑니다. 현재 지원 자격과 수강 요건은 모집 공지에서 확인하세요.'))}<div class="join-steps">${[[t('Explore','살펴보기'),t('Read a project story or open a PSIntelligence notebook. Notice which question makes you want to learn more.','프로젝트 이야기를 읽거나 PSIntelligence 노트북을 열어 보세요. 어떤 질문을 더 알아보고 싶은지 찾아보세요.')],[t('Meet & learn','만나고 배우기'),t('Follow the recruitment route, then take part in newcomer learning, practical work and member activities.','모집 절차를 확인하고, 참여 후에는 신입 교육과 실습, 회원 활동을 경험합니다.')],[t('Contribute','함께하기'),t('Build experience in group activity and discuss a research or competition interest with the team. Research-team participation is a further step.','공동 활동에서 경험을 쌓고 관심 있는 연구나 경진대회 활동을 팀과 이야기합니다. 연구팀 합류는 이후의 별도 단계입니다.')]].map(([title,body],i)=>`<article><span class="step-number">${i+1}</span><h3>${title}</h3><p>${body}</p></article>`).join('')}</div></section><section class="faq-section section"><div class="wrap split-content"><h2>${t('Before<br>you begin.','시작하기 전에<br>궁금한 것들.')}</h2><div class="faq-list">${[
 [t('Do I need previous rocket experience?','로켓 경험이 있어야 하나요?'),t('PSI provides newcomer education, practical learning and seminars. Check the latest recruitment notice for current prerequisites.','PSI에는 신입 교육, 실습, 세미나가 있습니다. 현재 선수 요건은 최신 모집 공지에서 확인하세요.')],
 [t('Who is eligible to apply?','누가 지원할 수 있나요?'),t('See the latest official recruitment notice for eligible academic affiliations and introductory requirements. These may vary by recruitment round.','지원 가능한 소속과 입문 요건은 최신 공식 모집 공지에서 확인하세요. 모집 차수에 따라 달라질 수 있습니다.')],
 [t('Do new members immediately join a research team?','신입 회원은 바로 연구팀에 들어가나요?'),t('No automatic assignment is promised. New members first take part in learning and group activities. Active research participation and a team leader’s recommendation can support a later move into a research team.','자동 배정을 약속하지 않습니다. 신입 회원은 먼저 교육과 활동에 참여하며, 적극적인 연구 참여와 팀장의 추천을 통해 이후 연구팀에 합류할 수 있습니다.')],
 [t('Is PSI only about rockets?','PSI는 로켓만 다루나요?'),t('No. The Aircraft Team designs and fabricates quadrotor and VTOL aircraft, and the research archive includes aircraft stability, education and other aerospace questions.','항공기팀은 쿼드로터와 VTOL 비행체를 설계하고 제작합니다. 연구 아카이브에는 항공기 안정성, 교육과 여러 항공우주 주제도 포함되어 있습니다.')],
 [t('Where can I find meeting times and locations?','모임 시간과 장소는 어디에서 확인하나요?'),t('Use the current group announcement. General meetings and research meetings have different purposes and may use different arrangements, so a permanent room or time is not listed here.','현재 연구회 공지를 확인해 주세요. 정기 모임과 연구 모임은 목적과 운영 방식이 다를 수 있어 이 페이지에는 고정된 장소나 시간을 기재하지 않습니다.')]
 ].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div></section><section class="wrap section contact-section"><div><h2>${t('Stay in touch.','PSI 소식 만나기.')}</h2><p>${t('For recruitment and activity updates, start with the official public channels. For technical questions, the relevant public repository gives you the project context.','모집과 활동 소식은 공식 공개 채널에서 확인하세요. 기술적인 질문을 살펴볼 때는 관련 공개 저장소에서 프로젝트의 맥락을 먼저 확인할 수 있습니다.')}</p></div><div class="contact-links">${link(sources.instagram,'Instagram <span>@postech_psi</span>','contact-link')}${link(sources.github,'GitHub <span>postech-psi</span>','contact-link')}${link(sources.legacy,t('PSI public introduction <span>Background & records</span>','PSI 공개 소개 <span>소개와 활동 기록</span>'),'contact-link')}</div></section>`;
 const bodies={index:home,projects,pslv,research:researchPage,learning,about,news:newsPage,join};
 return `<!doctype html><html lang="${lang}" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(loc(pageTitles[page]))}${page==='index'?'':' | PSI'}</title><meta name="description" content="${esc(t('PSI is a student aerospace research group at POSTECH. Explore rockets, aircraft, research and learning.','PSI는 포스텍 항공우주연구회입니다. 로켓, 항공기, 연구와 배움의 기록을 만나보세요.'))}"><script>try{const p=localStorage.getItem('psi-theme')||'system';document.documentElement.dataset.theme=p==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):p}catch(e){document.documentElement.dataset.theme=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}</script><link rel="preload" href="${asset}RedHatDisplay.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="${asset}Pretendard.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="${root}site.css"><script src="${root}site.js" defer></script></head><body><a class="skip-link" href="#main">${t('Skip to content','본문으로 바로가기')}</a><header class="site-header"><div class="header-inner"><a class="brand" href="index.html" aria-label="${t('PSI home','PSI 홈')}">${image('psi-logo.png','PSI','', 'eager')}</a><button class="menu-toggle" data-menu-toggle aria-controls="site-navigation" aria-expanded="false"><span data-menu-label>${t('Menu','메뉴')}</span><span class="menu-icon" aria-hidden="true"></span></button><nav id="site-navigation" class="site-nav" aria-label="${t('Main navigation','주 메뉴')}">${nav.map(([p,en,kr])=>`<a href="${href(p)}"${page===p||page==='pslv'&&p==='projects'?' aria-current="page"':''}>${t(en,kr)}</a>`).join('')}</nav><div class="header-preferences"><label class="theme-label"><span class="sr-only">${t('Colour theme','화면 테마')}</span><select data-theme-select aria-label="${t('Colour theme','화면 테마')}"><option value="system">${t('System','시스템')}</option><option value="light">${t('Light','라이트')}</option><option value="dark">${t('Dark','다크')}</option></select></label><a class="language-link" data-language-link href="${ko?'../':'ko/'}${page}.html" lang="${ko?'en':'ko'}" hreflang="${ko?'en':'ko'}" aria-label="${t('이 페이지를 한국어로 보기','Read this page in English')}">${t('한국어','EN')}</a></div></div></header><main id="main">${bodies[page]()}</main><footer class="site-footer"><div class="wrap footer-top"><div><a class="footer-wordmark" href="index.html">PSI</a><p>${t('Student aerospace research<br>at POSTECH.','포스텍 학생들의<br>항공우주 연구.')}</p></div><div class="footer-navigation">${nav.map(([p,en,kr])=>internal(p,t(en,kr),'')).join('')}</div><div class="footer-channels">${link(sources.instagram,'Instagram','')}${link(sources.github,'GitHub','')}${link(sources.legacy,t('Public introduction','공개 소개'),'')}</div></div><div class="wrap footer-bottom"><span>© ${new Date().getFullYear()} PSI</span><span>${t('POSTECH, Pohang, Republic of Korea','POSTECH, 대한민국 포항')}</span><a href="#main">${t('Back to top','맨 위로')}</a></div></footer></body></html>`;
}
